from __future__ import annotations


def page() -> str:
    return '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>MAL-Updater settings</title><style>
:root{--bg:#08111f;--card:#111d31;--ink:#f5f7fb;--muted:#a9b6ca;--brand:#7c9cff;--ok:#54d39b;--bad:#ff7f91}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 85% 0,#172b55,var(--bg) 45%);color:var(--ink);font:16px/1.5 system-ui,sans-serif}header,main{max-width:72rem;margin:auto;padding:1.2rem}header{display:flex;justify-content:space-between;align-items:center}nav a{color:var(--ink);margin-left:1rem}section{background:rgba(17,29,49,.95);border:1px solid #263958;border-radius:18px;padding:clamp(1rem,3vw,2rem);margin:1rem 0;box-shadow:0 18px 60px #0005}.grid,.settings-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(17rem,1fr));gap:1rem}.pill{display:inline-block;border-radius:999px;padding:.25rem .65rem;background:#263958;color:var(--muted)}label{display:block;margin:.8rem 0 .25rem}input,button{width:100%;padding:.75rem;border-radius:9px;border:1px solid #405477;background:#0b1526;color:var(--ink);font:inherit}button{background:var(--brand);color:#071126;border:0;font-weight:750;cursor:pointer;margin-top:1rem}button.secondary{background:#263958;color:var(--ink)}button:focus,input:focus,a:focus,summary:focus{outline:3px solid #b4c5ff;outline-offset:2px}.message{min-height:1.5rem;color:var(--ok)}.error{color:var(--bad)}small{display:block;color:var(--muted)}.credential-status,.test-result{margin-top:.2rem}.stored,.test-ok{color:var(--ok)}.not-stored,.test-failed{color:var(--bad)}details{border:1px solid #304566;border-radius:12px;margin:1rem 0;padding:.65rem 1rem}summary{cursor:pointer;font-weight:750;font-size:1.05rem}.setting{min-width:0}.setting small{min-height:3em}.restart{border-left:4px solid var(--brand);padding-left:.8rem}@media(max-width:520px){header{align-items:flex-start;flex-direction:column}nav a{margin:0 1rem 0 0}}
</style></head><body><header><strong>◉ MAL-Updater</strong><nav><a href="/">Dashboard</a><a href="/settings">Settings</a></nav></header><main><p id="msg" class="message" role="status" aria-live="polite"></p>
<section id="dashboard"><span class="pill">Trusted LAN control plane</span><h1>Configuration</h1><div class="grid"><div><h2>Setup</h2><p id="setupState"></p></div><div><h2>Automation</h2><p id="automationState"></p><small>The scheduler starts automatically when MAL setup is complete.</small></div><div><h2>Connections</h2><p id="connections"></p></div></div><p><small>MAL writes remain conservative and are not enabled merely by onboarding.</small></p></section>
<section id="settings"><h1>Credentials</h1><div class="grid"><form data-action="secrets"><h2>MAL application</h2><label>Client ID<input name="mal_client_id" autocomplete="off"><small id="malClientIdStatus" class="credential-status"></small></label><label>Client secret<input name="mal_client_secret" type="password" autocomplete="new-password"><small id="malClientSecretStatus" class="credential-status"></small></label><button>Save credentials</button><button type="button" class="secondary" id="malTest">Test MAL connection</button><small id="malTestResult" class="test-result" role="status" aria-live="polite">Not tested in this server session</small><button type="button" class="secondary" id="oauth">Connect MAL account</button></form><form data-action="secrets"><h2>Provider credentials</h2><label>Crunchyroll username<input name="crunchyroll_username" autocomplete="username"><small id="crunchyrollUsernameStatus" class="credential-status"></small></label><label>Crunchyroll password<input name="crunchyroll_password" type="password" autocomplete="new-password"><small id="crunchyrollPasswordStatus" class="credential-status"></small></label><button>Save Crunchyroll</button><button type="button" class="secondary test" data-provider="crunchyroll">Test Crunchyroll</button><small id="crunchyrollTestResult" class="test-result" role="status" aria-live="polite">Not tested in this server session</small><label>HIDIVE username<input name="hidive_username" autocomplete="username"><small id="hidiveUsernameStatus" class="credential-status"></small></label><label>HIDIVE password<input name="hidive_password" type="password" autocomplete="new-password"><small id="hidivePasswordStatus" class="credential-status"></small></label><button>Save HIDIVE</button><button type="button" class="secondary test" data-provider="hidive">Test HIDIVE</button><small id="hidiveTestResult" class="test-result" role="status" aria-live="polite">Not tested in this server session</small></form></div></section>
<section id="limits"><h1>Operational limits</h1><p>Customize request budgets, per-run bounds, pagination, pacing, retries, and learned-budget backoff. Values are numeric and bounded; this is not an arbitrary TOML editor.</p><p class="restart"><strong>Restart required.</strong> Saved changes apply after the scheduler/container restarts. The running scheduler and provider clients are not live-reloaded or mutated.</p><form id="settingsForm" data-action="settings"><div id="settingsFields"></div><button>Save operational limits</button></form></section></main><script>
let csrf='';const $=x=>document.querySelector(x),msg=(t,e=false)=>{let m=$('#msg');m.textContent=t;m.className=e?'message error':'message'},credential=(id,present)=>{let e=$(id);e.textContent=present?'Stored':'Not stored';e.className=`credential-status ${present?'stored':'not-stored'}`},testResult=(kind,result)=>{let e=$(`#${kind}TestResult`);if(!result){e.textContent='Not tested in this server session';e.className='test-result';return}e.textContent=result.message;e.className=`test-result ${result.ok?'test-ok':'test-failed'}`};async function api(path,body){if(body&&!csrf)await bootstrap();let r=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-CSRF-Token':csrf}:{},body:body?JSON.stringify(body):null,cache:'no-store'});let j=await r.json().catch(()=>({error:'Unexpected response'}));if(!r.ok)throw Error((j.error||'Request failed').replaceAll('_',' '));return j}async function bootstrap(){let r=await fetch('/api/csrf',{cache:'no-store'}),j=await r.json();if(!r.ok||!j.csrf_token)throw Error('Unable to initialize request protection');csrf=j.csrf_token}const valueAt=(value,path)=>path.split('.').reduce((item,key)=>item[key],value);function renderSettings(status){let root=$('#settingsFields');root.replaceChildren();let groups=new Map;for(let spec of status.settings_schema){if(!groups.has(spec.group))groups.set(spec.group,[]);groups.get(spec.group).push(spec)}for(let [name,specs] of groups){let details=document.createElement('details');details.open=['Scheduler cadence','Hourly request budgets','Per-run execution bounds','Provider pagination'].includes(name);let summary=document.createElement('summary');summary.textContent=name;details.append(summary);let grid=document.createElement('div');grid.className='settings-grid';for(let spec of specs){let label=document.createElement('label');label.className='setting';label.append(document.createTextNode(spec.label));let input=document.createElement('input');input.type='number';input.name=spec.path;input.min=spec.min;input.max=spec.max;input.step=spec.step;input.required=true;input.dataset.kind=spec.kind;input.value=valueAt(status.settings,spec.path);label.append(input);let help=document.createElement('small');help.textContent=spec.help+(spec.unit?` Unit: ${spec.unit}.`:'');label.append(help);grid.append(label)}details.append(grid);root.append(details)}}async function refresh(){let [s,r]=await Promise.all([api('/api/settings'),api('/api/status')]);$('#setupState').textContent=s.setup_complete?'Complete':'Needs MAL configuration and OAuth';$('#automationState').textContent=r.automation_state==='running'?'Running':s.setup_complete?'Blocked while scheduler starts or restarts':'Blocked until MAL setup is complete';$('#connections').textContent=`MAL OAuth: ${s.mal_oauth_complete?'connected':'not connected'} · Crunchyroll scheduler: ${s.providers.crunchyroll.scheduler_eligible?'active':'waiting for both credentials'} · HIDIVE scheduler: ${s.providers.hidive.scheduler_eligible?'active':'waiting for both credentials'}`;credential('#malClientIdStatus',s.secrets_present.mal_client_id);credential('#malClientSecretStatus',s.secrets_present.mal_client_secret);credential('#crunchyrollUsernameStatus',s.secrets_present.crunchyroll_username);credential('#crunchyrollPasswordStatus',s.secrets_present.crunchyroll_password);credential('#hidiveUsernameStatus',s.secrets_present.hidive_username);credential('#hidivePasswordStatus',s.secrets_present.hidive_password);for(let kind of ['mal','crunchyroll','hidive'])testResult(kind,s.connection_tests[kind]);renderSettings(s);if(s.settings_error)msg(s.settings_error,true)}document.addEventListener('submit',async e=>{e.preventDefault();let f=e.target;try{if(f.dataset.action==='settings'){let values={};for(let input of f.querySelectorAll('input[name]'))values[input.name]=input.dataset.kind==='int'?Number.parseInt(input.value,10):Number(input.value);let saved=await api('/api/settings',values);msg(saved.restart_required?'Operational limits saved. Restart the scheduler/container to apply them.':'Operational limits saved.');renderSettings(saved);return}let d=Object.fromEntries(new FormData(f)),replace={};for(let[k,v]of Object.entries(d))if(v)replace[k]=v;await api('/api/secrets',{replace,remove:[]});f.reset();msg('Credentials saved. They were not tested.');refresh()}catch(x){msg(x.message,true)}});$('#oauth').onclick=async()=>{try{let j=await api('/api/oauth/mal/start',{});location.href=j.authorization_url}catch(e){msg(e.message,true)}};document.querySelectorAll('.test').forEach(b=>b.onclick=()=>test(b.dataset.provider));$('#malTest').onclick=()=>test('mal');async function test(kind){try{let j=await api('/api/connections/test',{kind});msg(j.message);await refresh()}catch(e){msg(e.message,true);await refresh().catch(()=>{})}}bootstrap().then(refresh).catch(e=>msg(e.message,true));
</script></body></html>'''
